// ═══════════════════════════════════════════════════════════════
// Parse Step 2 — DYNAMIC (no hardcoded field names or SDS codes)
// ═══════════════════════════════════════════════════════════════
//
// Handles the AI's natural output shape (evaluation + content per field)
// and transforms it into field_results[] with DB-ready metadata.
//
// Uses field_code_map from Prepare Plan Data for SDS code lookups
// instead of a hardcoded mapping.

const item = $input.item.json;

// ── Unwrap AI output ──
let raw = item.output || item;
if (Array.isArray(raw)) raw = raw[0]?.output || raw[0] || raw;
if (raw.output && typeof raw.output === 'object') raw = raw.output;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) {
    const m = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (m) raw = JSON.parse(m[1]);
    else { const j = raw.match(/\{[\s\S]*\}/); if (j) raw = JSON.parse(j[0]); }
  }
}

// ── Locate the evaluation object ──
// The AI may wrap fields under different keys — check all known shapes
const evaluation = raw.treatment_plan_evaluation
  || raw.field_assessments
  || raw.plan_evaluation
  || raw;

// ── Get dynamic field info from upstream ──
const planData = $('Prepare Plan Data').item.json;
const fieldCodeMap = planData.field_code_map;     // { field_name: sds_code_id }
const knownFields = planData.field_names;          // ["client_context", "history", ...]
const planId = planData.plan_metadata.ai_treatment_plan_id;
const sessionId = planData.session.id;
const sessionDate = planData.session.date;
const clientId = raw.client_id || planData.session.client_id;

// ── Discover fields from the AI output ──
// Use BOTH the known DB fields AND whatever the AI returned
// This handles the case where the AI adds a new field or uses a slightly different name
function toSnakeCase(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

// Get all field names from the evaluation object, excluding metadata keys
const METADATA_KEYS = new Set([
  'client_id', 'session_date', 'deferred_observations', 'ai_recommendations',
  'schema_version', 'overall_assessment', 'session_summary'
]);

const aiFieldNames = Object.keys(evaluation).filter(k => !METADATA_KEYS.has(k));

// Merge: known DB fields + any new fields from AI output
const allFields = new Set([...knownFields, ...aiFieldNames.map(toSnakeCase)]);

// ── Process each field ──
const fieldResults = [];
let hasMaterialChanges = false;
let safetyRequiresReview = false;
let safetyContent = null;

for (const fieldName of allFields) {
  // Find matching data in AI output (try exact match, then snake_case variants)
  let fieldData = evaluation[fieldName];
  if (!fieldData) {
    // Try finding by iterating AI output keys
    for (const aiKey of Object.keys(evaluation)) {
      if (toSnakeCase(aiKey) === fieldName) {
        fieldData = evaluation[aiKey];
        break;
      }
    }
  }

  // If the AI didn't mention this field at all, it's implicitly "no_change"
  if (!fieldData) {
    fieldResults.push({
      field_name: fieldName,
      has_update: false,
      action: 'no_change',
      priority: 'routine',
      confidence: 'high',
      current_content: planData.current_plan[fieldName]?.content || null,
      proposed_content: null,
      ai_reasoning: 'Field not addressed in session analysis — no relevant content found.',
      change_summary: null,
      transcript_evidence: null,
      reviewer_attention: null,
      ai_treatment_plan_id: planId,
      sds_code_id: fieldCodeMap[fieldName] || 0,
      input_source_id: sessionId,
      session_date: sessionDate
    });
    continue;
  }

  // ── Normalize the decision structure ──
  // Shape A: { current_value, decision: { action, priority, rationale }, proposed_update }
  // Shape B: { has_update, action, decision_reasoning, evidence_references, ... }
  const decision = fieldData.decision || fieldData;
  const action = decision.action || 'no_change';
  const isUpdate = action !== 'no_change' && action !== 'unchanged';

  if (isUpdate) hasMaterialChanges = true;

  // ── Get proposed content ──
  let proposedContent = fieldData.proposed_update
    || fieldData.proposed_content
    || decision.proposed_update
    || null;

  const contentStr = (proposedContent !== null && typeof proposedContent === 'object')
    ? JSON.stringify(proposedContent)
    : proposedContent;

  // ── Get current value ──
  const currentValue = fieldData.current_value
    ?? (planData.current_plan[fieldName]?.content || null);

  // ── Build reasoning + metadata ──
  const rationale = decision.rationale || decision.decision_reasoning || '';
  const priority = decision.priority || 'routine';
  const confidence = decision.confidence || 'high';

  // Build change summary
  let changeSummary = null;
  if (isUpdate) {
    const friendlyName = fieldName.replace(/_/g, ' ');
    if (!currentValue) {
      changeSummary = `Initial documentation: ${friendlyName}`;
    } else if (action === 'replace') {
      changeSummary = `Updated ${friendlyName} based on new session information`;
    } else if (action === 'append') {
      changeSummary = `Added to ${friendlyName} from session findings`;
    } else {
      changeSummary = `${action}: ${friendlyName}`;
    }
  }

  // ── Safety detection ──
  const isSafetyField = fieldName === 'risk_assessment'
    || fieldName === 'safety'
    || fieldName.includes('risk')
    || fieldName.includes('safety');

  if (isSafetyField && isUpdate) {
    safetyRequiresReview = true;
    safetyContent = { proposed: contentStr, rationale, priority };
  }

  // ── Extract transcript evidence ──
  const evidenceRefs = fieldData.evidence_references || decision.evidence_references || [];
  const transcriptEvidence = Array.isArray(evidenceRefs)
    ? evidenceRefs.map(e => typeof e === 'string' ? e : (e.quote || e.verbatim_quote || '')).filter(Boolean).join(' | ')
    : (typeof evidenceRefs === 'string' ? evidenceRefs : '');

  // ── Goal-specific metadata (if this looks like a goals field) ──
  const goalDetails = fieldData.goal_details
    || decision.goal_details
    || fieldData.goal_specific
    || null;

  fieldResults.push({
    field_name: fieldName,
    has_update: isUpdate,
    action,
    priority,
    confidence,
    current_content: currentValue,
    proposed_content: contentStr,
    ai_reasoning: rationale,
    change_summary: changeSummary,
    transcript_evidence: transcriptEvidence || null,
    reviewer_attention: (priority === 'high' || priority === 'urgent')
      ? `Priority: ${priority}. ${rationale}`
      : null,
    goal_details: goalDetails,
    // DB-ready fields
    ai_treatment_plan_id: planId,
    sds_code_id: fieldCodeMap[fieldName] || 0,
    input_source_id: sessionId,
    session_date: sessionDate
  });
}

// ── Handle fields the AI returned that aren't in the DB yet ──
// (sds_code_id will be 0 — the DB write will need to handle this)
const unmappedFields = fieldResults
  .filter(f => f.has_update && f.sds_code_id === 0)
  .map(f => f.field_name);

// ── Session metadata ──
const deferredObs = raw.deferred_observations || evaluation.deferred_observations || [];
const aiRecs = raw.ai_recommendations || evaluation.ai_recommendations || [];

const sessionMeta = {
  _type: 'session_meta',
  has_material_changes: hasMaterialChanges,
  safety_requires_review: safetyRequiresReview,
  safety_content: safetyContent,
  client_id: clientId,
  session_id: sessionId,
  session_date: sessionDate,
  ai_treatment_plan_id: planId,
  deferred_observations: JSON.stringify(deferredObs),
  ai_recommendations: JSON.stringify(aiRecs),
  fields_with_updates: fieldResults.filter(f => f.has_update).map(f => f.field_name),
  fields_without_updates: fieldResults.filter(f => !f.has_update).map(f => f.field_name),
  unmapped_fields: unmappedFields,  // Fields the AI suggested that don't have sds_code_ids
  schema_version: raw.schema_version || '1.0'
};

return [{
  json: {
    session_meta: sessionMeta,
    field_results: fieldResults,
    updates: fieldResults.filter(f => f.has_update),
    update_count: fieldResults.filter(f => f.has_update).length,
    skip_count: fieldResults.filter(f => !f.has_update).length
  }
}];

// ═══════════════════════════════════════════════════════════════
// Build Non-Material Session Log
// ═══════════════════════════════════════════════════════════════
//
// When the gate determines no material changes, we still log the session.

const parsed = $input.item.json;
const meta = parsed.session_meta;
const step1 = $('Parse Step 1').first().json;

return [{
  json: {
    ai_treatment_plan_id: meta.ai_treatment_plan_id,
    session_id: meta.session_id,
    session_date: meta.session_date,
    session_summary: step1.session_summary || '',
    material_changes: false,
    fields_updated: '[]',
    deferred_observations: meta.deferred_observations || '[]',
    ai_recommendations: meta.ai_recommendations || '[]',
    safety_review_completed: false,
    safety_adequate: null,
    safety_reviewer_flags: null
  }
}];

const item = $input.item.json;
let data = item.output || item;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch (e) {
    const m = data.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (m) data = JSON.parse(m[1]);
    else { const j = data.match(/\{[\s\S]*\}/); if (j) data = JSON.parse(j[0]); }
  }
}
return [{ json: data }];

// ── Load template (sds_codes) ──
let templateRows = [];
try {
  const raw = $('Load Treatment Plan Codes').item.json;
  if (raw.data && Array.isArray(raw.data)) {
    templateRows = raw.data;
  } else if (raw.code_label && Array.isArray(raw.code_label)) {
    templateRows = raw.code_label.map((label, i) => ({
      code_label: label,
      sds_code_id: (raw.sds_code_id || raw.id || [])[i]
    }));
  }
} catch (e) {}

// ── Load existing plan items ──
let existingLabels = [], existingContents = [], existingDates = [];
let existingSourceIds = [], existingCodeIds = [], existingRowTypes = [];
try {
  const ex = $('Aggregate Plan Items').item.json;
  existingLabels = ex.code_label || [];
  existingContents = ex.item_content || [];
  existingDates = ex.updated_at || [];
  existingSourceIds = ex.input_source_id || [];
  existingCodeIds = ex.sds_code_id || [];
  existingRowTypes = ex.row_type || [];
} catch (e) {}

function toSnakeCase(label) {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

// ── Build template ──
const current_plan = {};
const field_code_map = {};

for (const row of templateRows) {
  const label = row.code_label || row.label;
  if (!label || label.includes('(ARCHIVE)')) continue;

  const field = toSnakeCase(label);
  const codeId = row.sds_code_id || row.id;

  field_code_map[field] = codeId;
  current_plan[field] = {
    content: null,
    approved_content: null,
    approved_date: null,
    pending_updates: [],
    last_updated: null,
    sds_code_id: codeId
  };
}

// ── Overlay existing content ──
// Data arrives ordered by sds_code_id, updated_at DESC (newest first)
// row_type = 'approved' or 'pending' from the CTE query
for (let i = 0; i < existingLabels.length; i++) {
  const rawLabel = existingLabels[i];
  if (!rawLabel) continue;

  const field = toSnakeCase(rawLabel);
  const content = existingContents[i] || null;
  const updatedAt = existingDates[i] || null;
  const sourceId = existingSourceIds[i] || null;
  const codeId = existingCodeIds[i] || null;
  const rowType = existingRowTypes[i] || 'pending';
  const isApproved = (rowType === 'approved');

  // Create entry if field not in template (legacy data)
  if (!current_plan[field]) {
    current_plan[field] = {
      content: null,
      approved_content: null,
      approved_date: null,
      pending_updates: [],
      last_updated: null,
      sds_code_id: codeId
    };
    if (codeId) field_code_map[field] = codeId;
  }

  if (!content) continue;
  const entry = current_plan[field];

  if (isApproved && !entry.approved_content) {
    // First (most recent) approved row = trusted baseline
    entry.approved_content = content;
    entry.approved_date = updatedAt;
    entry.content = content;
    entry.last_updated = updatedAt;
    entry.sds_code_id = codeId || field_code_map[field];
  } else if (!isApproved) {
    // Pending — only track if newer than approved baseline
    if (!entry.approved_date || (updatedAt && updatedAt > entry.approved_date)) {
      entry.pending_updates.push({ content, date: updatedAt });
    }
    // No approved version? Use latest pending as fallback
    if (!entry.approved_content && !entry.content) {
      entry.content = content;
      entry.last_updated = updatedAt;
      entry.sds_code_id = codeId || field_code_map[field];
    }
  }
}

// ── Build outputs ──
const field_names = Object.keys(current_plan);
const populated_fields = field_names.filter(f => current_plan[f].content !== null);
const empty_fields = field_names.filter(f => current_plan[f].content === null);
const approved_fields = field_names.filter(f => current_plan[f].approved_content !== null);
const pending_only_fields = populated_fields.filter(f => !current_plan[f].approved_content);
const fields_with_pending = field_names.filter(f => current_plan[f].pending_updates.length > 0);

const planId = $('Get Treatment Plan ID').item.json.get_or_create_ai_treatment_plan_id;
const sessionDate = $('Get AI Note Data').item.json.created_at;

const plan_for_ai = {};
for (const field of field_names) {
  plan_for_ai[field] = current_plan[field].content;
}

let pending_summary = null;
if (fields_with_pending.length > 0) {
  pending_summary = {};
  for (const field of fields_with_pending) {
    pending_summary[field] = current_plan[field].pending_updates
      .map(p => `[${p.date}] ${p.content.substring(0, 200)}...`)
      .join('\n');
  }
}

return [{
  json: {
    current_plan,
    plan_for_ai,
    pending_summary,
    field_names,
    field_code_map,
    plan_metadata: {
      ai_treatment_plan_id: planId,
      field_count: field_names.length,
      populated_count: populated_fields.length,
      empty_count: empty_fields.length,
      empty_fields,
      populated_fields,
      approved_fields,
      pending_only_fields,
      fields_with_pending,
      is_new_plan: populated_fields.length === 0
    },
    session: {
      id: $('Get AI Note Data').item.json.id,
      date: sessionDate,
      client_id: $('When Executed by Another Workflow').item.json.anonymizedName,
      transcript: $('When Executed by Another Workflow').item.json.anonymizedWebvtt
    }
  }
}];

// ═══════════════════════════════════════════════════════════════
// Safety Review Gate
// ═══════════════════════════════════════════════════════════════
// 
// This node checks: does the Step 2 output contain risk/safety content?
// If yes → route to Safety Review AI call
// If no  → skip directly to DB writes
//
// This is a CODE node feeding an IF node.
// Output: { needs_safety_review: boolean, safety_data: {...} }

const parsed = $input.item.json;
const meta = parsed.session_meta;

// Find the risk_assessment field result
const riskField = parsed.field_results.find(f => f.field_name === 'risk_assessment');

// Also scan ALL fields for safety-adjacent content the AI might have 
// placed in the wrong field (e.g., SI mention in presenting_concerns)
const SAFETY_KEYWORDS = [
  'suicid', 'self-harm', 'self harm', 'kill', 'die ', 'dying', 'want to die',
  'harm to others', 'homicid', 'violence', 'assault', 'weapon',
  'overdose', 'detox', 'withdrawal', 'seizure', 'DTs',
  'cutting', 'burning', 'not safe', 'unsafe', 'crisis',
  'passive si', 'active si', 'ideation', 'attempt', 'plan to'
];

function containsSafetyContent(text) {
  if (!text) return false;
  const lower = text.toLowerCase();
  return SAFETY_KEYWORDS.some(kw => lower.includes(kw));
}

// Check all proposed content for safety signals
const safetyInOtherFields = [];
for (const field of parsed.field_results) {
  if (field.field_name === 'risk_assessment') continue;
  if (field.proposed_content && containsSafetyContent(field.proposed_content)) {
    safetyInOtherFields.push({
      field: field.field_name,
      content_snippet: field.proposed_content.substring(0, 200),
      concern: 'Safety-relevant content may be routed to wrong field'
    });
  }
}

const needsReview = meta.safety_requires_review
  || (riskField && riskField.has_update)
  || safetyInOtherFields.length > 0;

return [{
  json: {
    needs_safety_review: needsReview,
    safety_data: {
      risk_field: riskField || null,
      safety_in_other_fields: safetyInOtherFields,
      deferred_observations: meta.deferred_observations
    },
    // Pass through everything else
    ...parsed
  }
}];

// ═══════════════════════════════════════════════════════════════
// Apply Safety Review — Merge safety findings back into results
// ═══════════════════════════════════════════════════════════════
//
// This runs AFTER the Safety Review AI call.
// It takes the safety review output and modifies the field_results
// if the safety reviewer flagged issues.

const safetyReview = $input.item.json;
let reviewData = safetyReview.output || safetyReview;

// Parse if string
if (typeof reviewData === 'string') {
  try { reviewData = JSON.parse(reviewData); } catch(e) {
    const m = reviewData.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (m) reviewData = JSON.parse(m[1]);
    else { const j = reviewData.match(/\{[\s\S]*\}/); if (j) reviewData = JSON.parse(j[0]); }
  }
}

// Get the current parsed data from upstream
const parsed = $('Parse Step 2').item.json;
const fieldResults = [...parsed.field_results]; // clone
const sessionMeta = { ...parsed.session_meta };

// ── Apply safety corrections ──

// 1. If safety reviewer provided revised content, update risk_assessment
if (reviewData.revised_risk_content) {
  const riskIdx = fieldResults.findIndex(f => f.field_name === 'risk_assessment');
  if (riskIdx >= 0) {
    fieldResults[riskIdx].proposed_content = reviewData.revised_risk_content;
    fieldResults[riskIdx].reviewer_attention =
      (fieldResults[riskIdx].reviewer_attention || '') +
      ' [Safety review: content was revised. ' + (reviewData.reviewer_flags || '') + ']';
  }
}

// 2. If severity was wrong, update priority
if (!reviewData.severity_appropriate && reviewData.recommended_severity) {
  const riskIdx = fieldResults.findIndex(f => f.field_name === 'risk_assessment');
  if (riskIdx >= 0) {
    const oldPriority = fieldResults[riskIdx].priority;
    fieldResults[riskIdx].priority = reviewData.recommended_severity;
    fieldResults[riskIdx].reviewer_attention =
      (fieldResults[riskIdx].reviewer_attention || '') +
      ` [Safety review: severity upgraded from ${oldPriority} to ${reviewData.recommended_severity}]`;
  }
}

// 3. If routing issues were found (safety content in wrong field), flag them
if (reviewData.routing_issues && reviewData.routing_issues.length > 0) {
  for (const issue of reviewData.routing_issues) {
    // Add reviewer_attention to the affected field
    const idx = fieldResults.findIndex(f => f.field_name === issue.field || f.field_name === issue);
    if (idx >= 0) {
      fieldResults[idx].reviewer_attention =
        (fieldResults[idx].reviewer_attention || '') +
        ' [Safety review: this field may contain safety-relevant content that should also appear in risk_assessment]';
    }
  }

  // If risk_assessment wasn't being updated but should be, add it
  const riskIdx = fieldResults.findIndex(f => f.field_name === 'risk_assessment');
  if (riskIdx >= 0 && !fieldResults[riskIdx].has_update) {
    fieldResults[riskIdx].has_update = true;
    fieldResults[riskIdx].action = 'populate';
    fieldResults[riskIdx].reviewer_attention =
      '[Safety review: routing issue detected — safety content found in other fields but risk_assessment was not being updated. Clinician review required.]';
  }
}

// 4. If missing follow-up questions, add to missing_information
if (reviewData.missing_follow_up_questions && reviewData.missing_follow_up_questions.length > 0) {
  const missingIdx = fieldResults.findIndex(f => f.field_name === 'missing_information');
  if (missingIdx >= 0) {
    const existingContent = fieldResults[missingIdx].proposed_content;
    const safetyQuestions = reviewData.missing_follow_up_questions;

    if (existingContent) {
      // Append safety follow-ups to existing missing info
      let parsed;
      try { parsed = JSON.parse(existingContent); } catch(e) { parsed = null; }

      if (Array.isArray(parsed)) {
        // Merge, avoiding duplicates
        for (const q of safetyQuestions) {
          if (!parsed.some(existing => existing.toLowerCase().includes(q.toLowerCase().substring(0, 30)))) {
            parsed.push('[Safety review] ' + q);
          }
        }
        fieldResults[missingIdx].proposed_content = JSON.stringify(parsed);
      } else {
        fieldResults[missingIdx].proposed_content =
          existingContent + '\n\n[From safety review]:\n' + safetyQuestions.map(q => '- ' + q).join('\n');
      }
    }

    if (!fieldResults[missingIdx].has_update) {
      fieldResults[missingIdx].has_update = true;
      fieldResults[missingIdx].action = 'append';
    }
  }
}

// 5. Add safety review summary to session meta
sessionMeta.safety_review_completed = true;
sessionMeta.safety_adequate = reviewData.safety_adequate;
sessionMeta.safety_reviewer_flags = reviewData.reviewer_flags || null;

return [{
  json: {
    session_meta: sessionMeta,
    field_results: fieldResults,
    updates: fieldResults.filter(f => f.has_update),
    update_count: fieldResults.filter(f => f.has_update).length,
    skip_count: fieldResults.filter(f => !f.has_update).length
  }
}];

// ═══════════════════════════════════════════════════════════════
// Prepare DB Writes — DYNAMIC
// ═══════════════════════════════════════════════════════════════
//
// Takes merged results and produces individual items for Postgres.
// Uses sds_code_id from the dynamic field_code_map — nothing hardcoded.
//
// Handles unmapped fields gracefully: logs a warning but doesn't crash.

const parsed = $input.item.json;
const meta = parsed.session_meta;
const results = parsed.field_results;

const outputItems = [];
const warnings = [];

// ── Plan item rows (fields with updates) ──
for (const field of results) {
  if (!field.has_update) continue;

  // Guard: if sds_code_id is 0/missing, this field isn't in the DB yet
  if (!field.sds_code_id) {
    warnings.push(`Field "${field.field_name}" has no sds_code_id — skipping DB insert. Add this field to sds_codes if you want it persisted.`);
    continue;
  }

  outputItems.push({
    json: {
      _type: 'plan_item',
      ai_treatment_plan_id: field.ai_treatment_plan_id,
      sds_code_id: field.sds_code_id,
      input_source_id: field.input_source_id,
      input_content: field.transcript_evidence || null,
      item_content_orig: field.proposed_content,
      item_content: field.proposed_content,
      // Extended fields (add columns to your table to use these)
      ai_reasoning: field.ai_reasoning || null,
      ai_confidence: field.confidence || null,
      ai_action: field.action || null,
      change_summary: field.change_summary || null,
      reviewer_attention: field.reviewer_attention || null,
      session_date: field.session_date || null,
      // Metadata for debugging
      _field_name: field.field_name
    }
  });
}

// ── Session log row (always) ──
const step1 = $('Parse Step 1').first().json;

outputItems.push({
  json: {
    _type: 'session_log',
    ai_treatment_plan_id: meta.ai_treatment_plan_id,
    session_id: meta.session_id,
    session_date: meta.session_date,
    session_summary: step1.session_summary || '',
    material_changes: meta.has_material_changes,
    fields_updated: JSON.stringify(meta.fields_with_updates || []),
    deferred_observations: meta.deferred_observations || '[]',
    ai_recommendations: meta.ai_recommendations || '[]',
    safety_review_completed: meta.safety_review_completed || false,
    safety_adequate: meta.safety_adequate ?? null,
    // Include any warnings about unmapped fields
    warnings: warnings.length > 0 ? JSON.stringify(warnings) : null
  }
});

// If there were unmapped fields but no other items, still return the session log
if (outputItems.length === 0) {
  return [{ json: { _type: 'session_log', error: 'No items to write', warnings: JSON.stringify(warnings) } }];
}

return outputItems;

